// oldData 旧数据，删除缓存时使用
func (c *CourseRepo) UpdateOneCacheWithZeroByTx(ctx context.Context, tx *yanxue_dao.Query, newData *yanxue_model.Course, oldData *yanxue_model.Course) error {
	dao := tx.Course
	_, err := dao.WithContext(ctx).Select(dao.ALL.WithTable("")).Updates(newData)
	if err != nil {
		return err
	}
	err = c.DeleteIndexCache(ctx, oldData, newData)
	if err != nil {
		return err
	}
	return nil
}

