// FindOneCacheByID 根据ID查询一条数据，并设置缓存
func (c *CourseRepo) FindOneCacheByID(ctx context.Context, ID string) (*yanxue_model.Course, error) {
	resp := new(yanxue_model.Course)
	cacheKey := c.cache.Key(CacheCourseByIDPrefix, ID)
	cacheValue, err := c.cache.Fetch2(ctx, cacheKey, func() (string, error) {
		dao := yanxue_dao.Use(c.db).Course
		result, err := dao.WithContext(ctx).Where(dao.ID.Eq(ID)).First()
		if err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			return "", err
		}
		marshal, err := c.encoding.Marshal(result)
		if err != nil {
			return "", err
		}
		return string(marshal), nil
	}, c.cache.TTL())
	if err != nil {
		return nil, err
	}
	if cacheValue != "" {
		err = c.encoding.Unmarshal([]byte(cacheValue), resp)
		if err != nil {
			return nil, err
		}
	}
	return resp, nil
}

