// FindMultiCacheByIDS 根据IDS查询多条数据，并设置缓存
func (c *CourseRepo) FindMultiCacheByIDS(ctx context.Context, IDS []string) ([]*yanxue_model.Course, error) {
	resp := make([]*yanxue_model.Course, 0)
	cacheKeys := make([]string, 0)
	keyToParam := make(map[string]string)
	for _, item := range IDS {
		cacheKey := c.cache.Key(CacheCourseByIDPrefix, item)
		cacheKeys = append(cacheKeys, cacheKey)
		keyToParam[cacheKey] = item
	}
	cacheValue, err := c.cache.FetchBatch2(ctx, cacheKeys, func(miss []string) (map[string]string, error) {
		dbValue := make(map[string]string)
		params := make([]string, 0)
		for _, item := range miss {
			dbValue[item] = ""
			params = append(params, keyToParam[item])
		}
		dao := yanxue_dao.Use(c.db).Course
		result, err := dao.WithContext(ctx).Where(dao.ID.In(params...)).Find()
		if err != nil {
			return nil, err
		}
		for _, item := range result {
			marshal, err := c.encoding.Marshal(item)
			if err != nil {
				return nil, err
			}
			dbValue[c.cache.Key(CacheCourseByIDPrefix, item.ID)] = string(marshal)
		}
		return dbValue, nil
	}, c.cache.TTL())
	if err != nil {
		return nil, err
	}
	for _, cacheKey := range cacheKeys {
		if cacheValue[cacheKey] != "" {
			tmp := new(yanxue_model.Course)
			err := c.encoding.Unmarshal([]byte(cacheValue[cacheKey]), tmp)
			if err != nil {
				return nil, err
			}
			resp = append(resp, tmp)
		}
	}
	return resp, nil
}

// FindMultiByCondition 自定义查询数据(通用)
// 非万能查询方法,请评估后谨慎使用
func (c *CourseRepo) FindMultiByCondition(ctx context.Context, conditionReq *condition.Req) ([]*yanxue_model.Course, *condition.Reply, error) {
	result := make([]*yanxue_model.Course, 0)
	conditionReply := &condition.Reply{}
	var total int64
	whereExpressions, orderExpressions, err := conditionReq.ConvertToGormExpression(yanxue_model.Course{})
	if err != nil {
		return result, conditionReply, err
	}
	if conditionReq.Page != 0 && conditionReq.PageSize != 0 {
		err = c.db.WithContext(ctx).Model(&yanxue_model.Course{}).Clauses(whereExpressions...).Count(&total).Error
		if err != nil {
			return result, conditionReply, err
		}
		if total == 0 {
			return result, conditionReply, nil
		}
		conditionReply, err = conditionReq.ConvertToPage(int32(total))
		if err != nil {
			return result, conditionReply, err
		}
		query := c.db.WithContext(ctx).Model(&yanxue_model.Course{}).Clauses(whereExpressions...).Clauses(orderExpressions...)
		if conditionReply.Page != 0 && conditionReply.PageSize != 0 {
			query = query.Offset(int((conditionReply.Page - 1) * conditionReply.PageSize))
			query = query.Limit(int(conditionReply.PageSize))
		}
		err = query.Find(&result).Error
		if err != nil {
			return result, conditionReply, err
		}
	} else {
		err = c.db.WithContext(ctx).Model(&yanxue_model.Course{}).Clauses(whereExpressions...).Clauses(orderExpressions...).Find(&result).Error
		if err != nil {
			return result, conditionReply, err
		}
		conditionReply.Total = int32(len(result))
	}
	return result, conditionReply, err
}

// FindMultiCacheByCondition 自定义查询数据(通用),并设置缓存
// 非万能查询方法,缓存命中率低,请评估后谨慎使用
func (c *CourseRepo) FindMultiCacheByCondition(ctx context.Context, conditionReq *condition.Req) ([]*yanxue_model.Course, *condition.Reply, error) {
	type Tmp struct {
		Result         []*yanxue_model.Course
		ConditionReply *condition.Reply
	}
	tmp := Tmp{
		Result:         make([]*yanxue_model.Course, 0),
		ConditionReply: &condition.Reply{},
	}
	cacheKey := c.cache.Key(CacheCourseByConditionPrefix)
	cacheField := conditionReq.ConvertToCacheField()
	cacheValue, err := c.cache.FetchHash2(ctx, cacheKey, cacheField, func() (string, error) {
		result, conditionReply, err := c.FindMultiByCondition(ctx, conditionReq)
		if err != nil {
			return "", err
		}
		tmp.Result = result
		tmp.ConditionReply = conditionReply
		marshal, err := c.encoding.Marshal(tmp)
		if err != nil {
			return "", err
		}
		return string(marshal), nil
	}, c.cache.TTL())
	if err != nil {
		return tmp.Result, tmp.ConditionReply, err
	}
	if cacheValue != "" {
		err = c.encoding.Unmarshal([]byte(cacheValue), &tmp)
		if err != nil {
			return tmp.Result, tmp.ConditionReply, err
		}
	}
	return tmp.Result, tmp.ConditionReply, nil
}

