// DeleteUniqueIndexCache 删除索引存在的缓存
func (c *CourseRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.Course) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, c.cache.Key(CacheCourseByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[c.cache.Key(CacheCourseByIDPrefix, item.ID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := c.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
